# ============================================================================
# 07e_motif_jaspar_bgd.R — Fig. 2c 的输入：差异可及区域的基序富集（CIS-BP，GC 与可及性匹配的背景 peak）
# 运行位置：服务器（conda 环境 Archr）；路径变量见 config/paths.R
# ============================================================================

source(file.path(Sys.getenv("MHP_CODE", "."), "config", "paths.R"))

suppressPackageStartupMessages({ library(ArchR); library(BSgenome.Sscrofa.Ensembl.v11.1); library(dplyr) })
addArchRChrPrefix(chrPrefix = FALSE); addArchRThreads(threads = 62); set.seed(42)
PROJ_DIR <- MHP_ARCHR; OUT_DIR <- file.path(PROJ_DIR, "ArchR_filtered")
SE_DIR <- file.path(PROJ_DIR, "outputs", "07_infection_DA", "SE_rds"); ENR_DIR <- file.path(PROJ_DIR, "outputs", "07_infection_DA", "MotifEnrich"); dir.create(ENR_DIR, showWarnings = FALSE)
proj <- loadArchRProject(OUT_DIR, showLogo = FALSE)
ct_order <- c("Macrophages","Neutrophils","T_NK_cells","Plasma_cells","B_cells","Epithelial_cells","Endothelial_cells","Fibroblasts")
A <- file.path(OUT_DIR, "Annotations"); cat("peakAnnotation:", paste(names(proj@peakAnnotation), collapse = ", "), "\n"); print(list.files(A))

# ============= B：Motif(=JASPAR) 改名为 MotifJ，然后 JASPAR 富集（全 peak 背景，与 cisbp 那轮同口径）=============
pa <- proj@peakAnnotation$Motif; cat("当前 Motif 里 motif 数:", length(pa$motifs), "（746 = 被 JASPAR 覆盖的状态；870 = cisbp）\n")
if (length(pa$motifs) == 746 && !"MotifJ" %in% names(proj@peakAnnotation)) { for (s in c("Positions-In-Peaks","Matches-In-Peaks","In-Peaks-Summary")) if (file.exists(file.path(A, paste0("Motif-", s, ".rds")))) file.rename(file.path(A, paste0("Motif-", s, ".rds")), file.path(A, paste0("MotifJ-", s, ".rds"))); pa$Name <- "MotifJ"; pa$Positions <- file.path(A, "MotifJ-Positions-In-Peaks.rds"); pa$Matches <- file.path(A, "MotifJ-Matches-In-Peaks.rds"); proj@peakAnnotation$MotifJ <- pa; proj@peakAnnotation <- proj@peakAnnotation[names(proj@peakAnnotation) != "Motif"]; cat("改名完成\n") } else cat("⚠ 状态不对，停下贴我\n")
cat("peakAnnotation:", paste(names(proj@peakAnnotation), collapse = ", "), "\n"); print(list.files(A)); saveArchRProject(proj, OUT_DIR, load = FALSE)
enr_j <- function(ct, dir) { se <- readRDS(file.path(SE_DIR, paste0(ct, "_MhpvsMock_DAPeak.rds"))); cut <- if (dir == "up") "FDR <= 0.05 & Log2FC >= 0.5" else "FDR <= 0.05 & Log2FC <= -0.5"; e <- tryCatch(peakAnnoEnrichment(seMarker = se, ArchRProj = proj, peakAnnotation = "MotifJ", cutOff = cut), error = function(x) { message(ct, " ", dir, ": ", conditionMessage(x)); NULL }); if (is.null(e)) return(NULL); data.frame(celltype = ct, direction = dir, motif = rownames(e), mlog10p = as.numeric(assay(e, "mlog10p")[, 1]), mlog10Padj = as.numeric(assay(e, "mlog10Padj")[, 1]), Enrichment = as.numeric(assay(e, "Enrichment")[, 1]), nCompare = as.numeric(assay(e, "CompareFrequency")[, 1]), stringsAsFactors = FALSE) }
enrJ <- bind_rows(lapply(ct_order[ct_order != "B_cells"], function(ct) bind_rows(enr_j(ct, "up"), enr_j(ct, "down")))) %>% group_by(celltype, direction) %>% mutate(rank = rank(-mlog10Padj, ties.method = "min")) %>% ungroup(); write.csv(enrJ, file.path(ENR_DIR, "DAR_motif_enrichment_JASPAR2020.csv"), row.names = FALSE)
cat("=== JASPAR2020：BHLHE40 在各类型 up/down DAR ===\n"); print(as.data.frame(enrJ %>% filter(grepl("BHLHE40", motif, ignore.case = TRUE)) %>% select(celltype, direction, motif, rank, mlog10p, mlog10Padj, Enrichment, nCompare) %>% arrange(direction, rank) %>% mutate(across(where(is.numeric), ~signif(.x, 3)))), row.names = FALSE)
for (dr in c("up","down")) { r <- enrJ %>% filter(celltype == "Macrophages", direction == dr) %>% arrange(rank); cat("\n=== JASPAR2020 巨噬", dr, "top 15 ===\n"); print(as.data.frame(head(r[, c("motif","mlog10p","mlog10Padj","Enrichment","nCompare")], 15) %>% mutate(across(where(is.numeric), ~signif(.x, 3)))), row.names = FALSE) }

# ============= C：cisbp 恢复回 Motif（~10 min），再用 ChromVAR 配平背景 bgdPeaks 重算巨噬+中性粒 up/down（cisbp + JASPAR 两库；中性粒因 JASPAR 全峰背景下 BHLHE40 Padj 0.0012 需验证）=============
proj <- addMotifAnnotations(ArchRProj = proj, motifSet = "cisbp", annoName = "Motif", species = "Homo sapiens", force = TRUE); saveArchRProject(proj, OUT_DIR, load = FALSE)
cat("peakAnnotation:", paste(names(proj@peakAnnotation), collapse = ", "), "| Motif 里 motif 数:", length(proj@peakAnnotation$Motif$motifs), "（应 870）\n")
eb <- function(ct, dir, anno) { se <- readRDS(file.path(SE_DIR, paste0(ct, "_MhpvsMock_DAPeak.rds"))); cut <- if (dir == "up") "FDR <= 0.05 & Log2FC >= 0.5" else "FDR <= 0.05 & Log2FC <= -0.5"; e <- peakAnnoEnrichment(seMarker = se, ArchRProj = proj, peakAnnotation = anno, cutOff = cut, background = "bgdPeaks"); data.frame(celltype = ct, direction = dir, lib = anno, motif = rownames(e), mlog10p = as.numeric(assay(e, "mlog10p")[, 1]), mlog10Padj = as.numeric(assay(e, "mlog10Padj")[, 1]), Enrichment = as.numeric(assay(e, "Enrichment")[, 1]), nCompare = as.numeric(assay(e, "CompareFrequency")[, 1]), stringsAsFactors = FALSE) }
enrB <- bind_rows(lapply(c("Motif","MotifJ"), function(a) bind_rows(lapply(c("Macrophages","Neutrophils"), function(ct) bind_rows(eb(ct, "up", a), eb(ct, "down", a)))))) %>% group_by(lib, celltype, direction) %>% mutate(rank = rank(-mlog10Padj, ties.method = "min")) %>% ungroup(); write.csv(enrB, file.path(ENR_DIR, "Mac_Neut_motif_enrichment_bgdPeaks_cisbp_JASPAR.csv"), row.names = FALSE)
for (a in c("Motif","MotifJ")) for (ct in c("Macrophages","Neutrophils")) for (dr in c("up","down")) { r <- enrB %>% filter(lib == a, celltype == ct, direction == dr) %>% arrange(rank); cat("\n===", ifelse(a == "Motif", "cisbp", "JASPAR2020"), "+ 配平背景", ct, dr, "top 10 ===\n"); print(as.data.frame(head(r[, c("motif","mlog10p","mlog10Padj","Enrichment","nCompare")], 10) %>% mutate(across(where(is.numeric), ~signif(.x, 3)))), row.names = FALSE); b <- r[grepl("^BHLHE40", r$motif), ]; cat("BHLHE40 排名:", b$rank, "| -log10Padj", signif(b$mlog10Padj, 3), "| 富集", signif(b$Enrichment, 3), "\n") }

eb <- function(ct, dir, anno = "Motif") { se <- readRDS(file.path(SE_DIR, paste0(ct, "_MhpvsMock_DAPeak.rds"))); cut <- if (dir == "up") "FDR <= 0.05 & Log2FC >= 0.5" else "FDR <= 0.05 & Log2FC <= -0.5"; e <- peakAnnoEnrichment(seMarker = se, ArchRProj = proj, peakAnnotation = anno, cutOff = cut, background = "bgdPeaks"); data.frame(celltype = ct, direction = dir, lib = anno, motif = rownames(e), mlog10p = as.numeric(assay(e, "mlog10p")[, 1]), mlog10Padj = as.numeric(assay(e, "mlog10Padj")[, 1]), Enrichment = as.numeric(assay(e, "Enrichment")[, 1]), nHit = as.numeric(assay(e, "CompareFrequency")[, 1]), nDAR = as.numeric(assay(e, "nCompare")[, 1]), nBgd = as.numeric(assay(e, "nBackground")[, 1]), stringsAsFactors = FALSE) }
sets10 <- list(c("Macrophages","up"), c("Macrophages","down"), c("Neutrophils","up"), c("Neutrophils","down"), c("T_NK_cells","up"), c("T_NK_cells","down"), c("Plasma_cells","down"), c("Epithelial_cells","up"), c("Epithelial_cells","down"), c("Fibroblasts","up"))
enrC <- bind_rows(lapply(sets10, function(x) eb(x[1], x[2]))) %>% mutate(set = paste0(celltype, "_", direction), TF = sub("_\\d+$", "", motif)) %>% group_by(set) %>% mutate(rank = rank(-mlog10Padj, ties.method = "min")) %>% ungroup(); write.csv(enrC, file.path(ENR_DIR, "DAR_motif_enrichment_cisbp_bgdPeaks_10sets.csv"), row.names = FALSE)
print(as.data.frame(enrC %>% group_by(set) %>% summarise(nDAR = nDAR[1], nBgd = nBgd[1], n_sig = sum(mlog10Padj > 1.3), top3 = paste(head(TF[order(-mlog10Padj)], 3), collapse = "/"))))
for (s in unique(enrC$set)[5:10]) { r <- enrC %>% filter(set == s) %>% arrange(rank); cat("\n===", s, " top 8 ===\n"); print(as.data.frame(head(r[, c("TF","mlog10Padj","Enrichment","nHit")], 8) %>% mutate(across(where(is.numeric), ~signif(.x, 3)))), row.names = FALSE) }
